from collections import namedtuple
from fractions import Fraction
from itertools import combinations
from pathlib import Path
from typing import Dict, List, Sequence, Tuple
import re
import subprocess

SIGMA = (-1, -1, -1, 1, 1, 1)
MINUS_IDX = (0, 1, 2)
PLUS_IDX = (3, 4, 5)


def parse_fraction(text: str) -> Fraction:
    t = text.strip()
    if not t:
        raise ValueError("empty rational token")
    if t[0] == "+":
        t = t[1:]
    if "/" in t:
        num, den = t.split("/")
        return Fraction(int(num), int(den))
    return Fraction(int(t), 1)


def fraction_to_str(value: Fraction) -> str:
    if value.denominator == 1:
        return str(value.numerator)
    return f"{value.numerator}/{value.denominator}"


def _fmt_list(values: Sequence[Fraction]) -> str:
    return ",".join(fraction_to_str(v) for v in values)


class KinematicsPoint:
    """Immutable exact kinematics point in the fixed ordering
    (-a, b, c, d, e, -f) with sigma=(-,-,-,+,+,+)."""

    def __init__(self, b, c, d, e):
        self.b = Fraction(b)
        self.c = Fraction(c)
        self.d = Fraction(d)
        self.e = Fraction(e)

        S = self.b + self.c + self.d + self.e
        if S == 0:
            raise ValueError("degenerate S=0")
        r = self.b * self.c - self.d * self.e
        self.a = self.d + self.e + r / S
        self.f = self.b + self.c - r / S

        self.omega = (-self.a, self.b, self.c, self.d, self.e, -self.f)

        self.pair_q: Dict[str, Fraction] = {}
        for m in MINUS_IDX:
            for p in PLUS_IDX:
                self.pair_q[f"q_{m+1}_{p+1}"] = self.omega[p] * self.omega[p] - self.omega[m] * self.omega[m]

        self.triple_q: Dict[str, Fraction] = {}
        for m in MINUS_IDX:
            for p, q in combinations(PLUS_IDX, 2):
                self.triple_q[f"q_{m+1}_{p+1}{q+1}"] = (
                    self.omega[p] * self.omega[p] + self.omega[q] * self.omega[q] - self.omega[m] * self.omega[m]
                )

        self.delta = Fraction(1, 1)
        for m in MINUS_IDX:
            for p in PLUS_IDX:
                self.delta *= self.omega[m] + self.omega[p]

    def sorted_magnitude_word(self) -> Tuple[str, bool, List[int]]:
        entries = [(i, abs(w * w)) for i, w in enumerate(self.omega)]
        sorted_entries = sorted(entries, key=lambda t: (t[1], t[0]), reverse=True)
        strict = all(
            sorted_entries[i][1] != sorted_entries[i + 1][1]
            for i in range(len(sorted_entries) - 1)
        )
        signs = ["+" if SIGMA[i] > 0 else "-" for i, _ in sorted_entries]
        order = [i for i, _ in sorted_entries]
        return "".join(signs), strict, order

    def momentum_subset_signs(self) -> str:
        terms = [Fraction(si, 1) * w * w for si, w in zip(SIGMA, self.omega)]
        bits: List[str] = []
        for mask in range(1, (1 << len(terms)) - 1):
            s = Fraction(0, 1)
            for i, v in enumerate(terms):
                if mask & (1 << i):
                    s += v
            if s == 0:
                bits.append("0")
            else:
                bits.append("+" if s > 0 else "-")
        return "".join(bits)

    def conservation_checks(self) -> Dict[str, object]:
        sum_omega = sum(self.omega)
        sum_momentum = sum(si * w * w for si, w in zip(SIGMA, self.omega))
        return {
            "sum_omega": sum_omega,
            "sum_omega_ok": sum_omega == 0,
            "sum_momentum": sum_momentum,
            "sum_momentum_ok": sum_momentum == 0,
        }

    def pair_sign_pattern(self) -> Tuple[Tuple[str, ...], Tuple[str, ...]]:
        keys: List[str] = []
        signs: List[str] = []
        for m in MINUS_IDX:
            for p in PLUS_IDX:
                key = f"q_{m+1}_{p+1}"
                value = self.pair_q[key]
                keys.append(key)
                signs.append("0" if value == 0 else "+" if value > 0 else "-")
        return tuple(signs), tuple(keys)

    def triple_sign_pattern(self) -> Tuple[Tuple[str, ...], Tuple[str, ...]]:
        keys: List[str] = []
        signs: List[str] = []
        for m in MINUS_IDX:
            for p, q in combinations(PLUS_IDX, 2):
                key = f"q_{m+1}_{p+1}{q+1}"
                value = self.triple_q[key]
                keys.append(key)
                signs.append("0" if value == 0 else "+" if value > 0 else "-")
        return tuple(signs), tuple(keys)

    def is_generic(self, require_nonzero=True) -> bool:
        checks = self.conservation_checks()
        if not checks["sum_omega_ok"] or not checks["sum_momentum_ok"]:
            return False
        if require_nonzero and not self.sorted_magnitude_word()[1]:
            return False
        if require_nonzero:
            if any(v == 0 for v in self.pair_q.values()):
                return False
            if any(v == 0 for v in self.triple_q.values()):
                return False
        return True

    def as_json_record(self) -> Dict[str, object]:
        pair_signs, pair_keys = self.pair_sign_pattern()
        triple_signs, triple_keys = self.triple_sign_pattern()
        word, strict, order = self.sorted_magnitude_word()
        checks = self.conservation_checks()
        return {
            "b": fraction_to_str(self.b),
            "c": fraction_to_str(self.c),
            "d": fraction_to_str(self.d),
            "e": fraction_to_str(self.e),
            "S": fraction_to_str(self.b + self.c + self.d + self.e),
            "r": fraction_to_str(self.b * self.c - self.d * self.e),
            "a": fraction_to_str(self.a),
            "f": fraction_to_str(self.f),
            "omega": [fraction_to_str(x) for x in self.omega],
            "sorted_word": word,
            "sorted_word_strict": strict,
            "sorted_order": order,
            "pair_keys": list(pair_keys),
            "pair_signs": list(pair_signs),
            "pair_q": {k: fraction_to_str(v) for k, v in self.pair_q.items()},
            "triple_keys": list(triple_keys),
            "triple_signs": list(triple_signs),
            "triple_q": {k: fraction_to_str(v) for k, v in self.triple_q.items()},
            "delta": fraction_to_str(self.delta),
            "subset_signature": self.momentum_subset_signs(),
            "sum_omega": fraction_to_str(checks["sum_omega"]),
            "sum_momentum": fraction_to_str(checks["sum_momentum"]),
            "is_strict": strict,
        }


BGResult = namedtuple("BGResult", ["n", "sigma", "omega", "amp_re", "amp_im", "command", "stdout"])


class BGOracleError(RuntimeError):
    pass


class BGOracle:
    """Wrapper for the local exact bg.cpp binary."""

    OMEGA_RE = re.compile(r"omega\s*=\s*\{([^}]*)\}")
    AMP_RE = re.compile(r"A_(\d+)\s*=\s*\(([^)]*)\)\s*\+\s*i\s*\(([^)]*)\)")
    PURE_IM_RE = re.compile(r"A_(\d+)\s*=\s*i\s*\*\s*\(([^)]*)\)")

    def __init__(self, binary_path: str = "bg", default_sigma=None):
        self.binary_path = str(Path(binary_path))
        self.default_sigma = tuple(int(x) for x in (default_sigma if default_sigma is not None else SIGMA))
        self._cache: Dict[tuple, BGResult] = {}

    @staticmethod
    def _fmt(vals: Sequence[Fraction]) -> str:
        return _fmt_list(vals)

    def _run(self, args: Sequence[str], timeout: int = 20) -> str:
        cmd = [self.binary_path] + list(args)
        try:
            proc = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=timeout)
        except FileNotFoundError as exc:
            raise BGOracleError(f"bg executable not found: {self.binary_path}") from exc
        except subprocess.TimeoutExpired as exc:
            raise BGOracleError(f"bg timed out after {timeout}s") from exc
        if proc.returncode != 0:
            raise BGOracleError(f"bg failed ({proc.returncode}): {proc.stderr.strip()}")
        return proc.stdout

    @classmethod
    def _parse_fraction(cls, token: str) -> Fraction:
        return parse_fraction(token)

    def _parse_output(self, text: str, n: int) -> BGResult:
        m_omega = self.OMEGA_RE.search(text)
        if not m_omega:
            raise BGOracleError("failed parsing omega from BG output")
        omega_raw = [part.strip() for part in m_omega.group(1).split(",") if part.strip()]
        if len(omega_raw) != n:
            raise BGOracleError(f"expected {n} omegas, got {len(omega_raw)}")
        omega = tuple(self._parse_fraction(v) for v in omega_raw)

        m_complex = self.AMP_RE.search(text)
        m_pure = self.PURE_IM_RE.search(text)
        amp_re = Fraction(0, 1)
        amp_im = Fraction(0, 1)
        if m_complex:
            got_n = int(m_complex.group(1))
            if got_n != n:
                raise BGOracleError("amplitude index mismatch in BG output")
            amp_re = self._parse_fraction(m_complex.group(2))
            amp_im = self._parse_fraction(m_complex.group(3))
        elif m_pure:
            got_n = int(m_pure.group(1))
            if got_n != n:
                raise BGOracleError("amplitude index mismatch in BG output")
            amp_im = self._parse_fraction(m_pure.group(2))
        else:
            raise BGOracleError("failed parsing amplitude from BG output")
        return BGResult(n=n, sigma=self.default_sigma, omega=omega, amp_re=amp_re, amp_im=amp_im, command=tuple(), stdout=text)

    def solve_on_shell(self, free_w, sigma=None, g: int = 1, n: int = 6):
        if n != 6:
            raise BGOracleError("this implementation is configured for n=6")
        if len(free_w) != n - 2:
            raise BGOracleError(f"expected {n-2} free frequencies, got {len(free_w)}")

        sigma_tuple = tuple(int(x) for x in (sigma if sigma is not None else self.default_sigma))
        if len(sigma_tuple) != n:
            raise BGOracleError("sigma length mismatch")

        key = (
            "shell",
            tuple(self._normalize_token(x) for x in free_w),
            sigma_tuple,
            n,
            g,
        )
        if key in self._cache:
            return self._cache[key]

        args = [
            "-n",
            str(n),
            "-w",
            self._fmt([Fraction(x) for x in free_w]),
            "-s",
            ",".join(str(int(x)) for x in sigma_tuple),
            "-g",
            str(g),
        ]
        out = self._run(args)
        parsed = self._parse_output(out, n)
        result = BGResult(
            n=n,
            sigma=sigma_tuple,
            omega=parsed.omega,
            amp_re=parsed.amp_re,
            amp_im=parsed.amp_im,
            command=(self.binary_path,) + tuple(args),
#!/usr/bin/env python3
"""Exact bottom-up reconstruction of pair-wall bricks for round 3.

The amplitude oracle and compact pole subtraction are imported from the
round-2 driver.  Cell polynomials are reconstructed in the homogeneous
on-shell quotient basis after eliminating omega_6.  Large exact linear
systems are delegated to the locally installed Wolfram kernel; all sampling,
rank certification, quotient checks, and holdouts remain in this driver.
"""

import argparse
import importlib.util
import json
import random
import shutil
import subprocess
import time
from fractions import Fraction
from pathlib import Path

import sympy as sp


HERE = Path(__file__).resolve()
ROOT = HERE.parents[3]
BOT = ROOT / "bots" / "student-2"
DATA = BOT / "data"
WOLFRAM = Path("/opt/sns/bin/WolframKernel")


def load_round2():
    path = HERE.with_name("round2_exact.py")
    spec = importlib.util.spec_from_file_location("round2_exact_local", str(path))
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


R2 = load_round2()


def fstr(x):
    x = Fraction(x)
    return str(x.numerator) if x.denominator == 1 else "%d/%d" % (x.numerator, x.denominator)


def parse_fraction(text):
    return Fraction(str(text).replace(" ", ""))


def homogeneous_basis(degree):
    """Exponent tuples for w1,...,w5, with exponent(w5) <= 1."""
    ans = []
    for e5 in range(min(1, degree) + 1):
        rem = degree - e5
        for e1 in range(rem + 1):
            for e2 in range(rem - e1 + 1):
                for e3 in range(rem - e1 - e2 + 1):
                    e4 = rem - e1 - e2 - e3
                    ans.append((e1, e2, e3, e4, e5))
    return ans


def signature(point, include_energy=True):
    pair, triple = point.sign_maps()
    values = []
    keys = []
    if include_energy:
        for i, w in enumerate(point.omega):
            keys.append("omega_%d" % (i + 1))
            values.append("+" if w > 0 else "-" if w < 0 else "0")
    for key in sorted(pair):
        keys.append(key)
        values.append(pair[key])
    for key in sorted(triple):
        keys.append(key)
        values.append(triple[key])
    return tuple(values), tuple(keys)


def generic_oracle_point(point):
    if not point.is_generic() or point.C == 0:
        return False
    for m in R2.MINUS_IDX:
        for p in R2.PLUS_IDX:
            if point.omega[m] + point.omega[p] == 0:
                return False
    return True


def scaled_w(point):
    """Integer W=S*omega for integral free parameters."""
    S = point.b + point.c + point.d + point.e
    vals = [w * S for w in point.omega[:5]]
    if any(v.denominator != 1 for v in vals):
        raise AssertionError("scaled coordinates were not integral")
    return tuple(v.numerator for v in vals), S


def eval_row_int(W, basis):
    powers = []
    degree = sum(basis[0])
    for x in W:
        powers.append([pow(x, k) for k in range(degree + 1)])
    return [
        powers[0][e[0]] * powers[1][e[1]] * powers[2][e[2]]
        * powers[3][e[3]] * powers[4][e[4]]
        for e in basis
    ]


class ModularRank:
    """Incremental row-rank selection over a prime field."""

    def __init__(self, ncols, prime=1000000007):
        self.ncols = ncols
        self.p = prime
        self.rows = {}

    def add(self, row):
        p = self.p
        v = [x % p for x in row]
        for pivot in sorted(self.rows):
            if v[pivot]:
                factor = v[pivot]
                base = self.rows[pivot]
                for j in range(pivot, self.ncols):
                    v[j] = (v[j] - factor * base[j]) % p
        pivot = next((j for j, x in enumerate(v) if x), None)
        if pivot is None:
            return False
        inv = pow(v[pivot], p - 2, p)
        for j in range(pivot, self.ncols):
            v[j] = v[j] * inv % p
        # Reduced pivots make later row processing cheaper and deterministic.
        for old, base in list(self.rows.items()):
            if base[pivot]:
                factor = base[pivot]
                self.rows[old] = [
                    (base[j] - factor * v[j]) % p if j >= old else base[j]
                    for j in range(self.ncols)
                ]
        self.rows[pivot] = v
        return True

    @property
    def rank(self):
        return len(self.rows)


def center_for(seed, side, scale=120, offset=6):
    B, c, e = seed
    # b<d is the L side; b>d is the R side.
    b = scale * B // 2 + (-offset if side == "L" else offset)
    d = scale * B // 2 + (offset if side == "L" else -offset)
    return (b, scale * c, d, scale * e)


def target_signature(seed, side):
    B, c, e = seed
    eps = Fraction(1, 1000)
    t = Fraction(B, 2) + (-eps if side == "L" else eps)
    point = R2.SixPoint(t, c, Fraction(B) - t, e)
    return signature(point)


def candidate_stream(seed, side, rng):
    """Local integral points in the same open conic cell."""
    center = center_for(seed, side)
    radius = 34
    while True:
        # A common positive rescaling moves through the cone; independent
        # integral perturbations provide generic projective directions.
        mult = rng.randint(1, 5)
        vals = [
            mult * x + rng.randint(-radius, radius)
            for x in center
        ]
        if sum(vals) == 0:
            continue
        try:
            yield R2.SixPoint(*vals)
        except Exception:
            continue


def evaluate_remainder(oracle, point):
    result, err = R2.safe_on_shell(
        oracle, 6, [point.b, point.c, point.d, point.e]
    )
    if result is None:
        raise RuntimeError("BG failure: %s" % err)
    omega, re_part, im_part = result
    if re_part != 0 or tuple(omega) != tuple(point.omega):
        raise AssertionError("oracle mismatch")
    remainder, pole, _ = R2.wall_pole_subtracted(point, im_part)
    return remainder, im_part, pole


def build_fresh_oracle():
    src = ROOT / "bg.cpp"
    dst = BOT / "bg.cpp"
    shutil.copy2(str(src), str(dst))
    binary = BOT / "bg"
    cmd = [
        "g++", "-O2", "-std=c++17", "-o", str(binary), str(dst),
        "-lgmpxx", "-lgmp",
    ]
    proc = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                          universal_newlines=True)
    if proc.returncode:
        raise RuntimeError(proc.stderr)
    return R2.BGOracle(binary), cmd


def reconstruct_branch(oracle, seed, side, basis, rng, tag, holdouts=20):
    target, sig_keys = target_signature(seed, side)
    ranker = ModularRank(len(basis))
    selected = []
    attempts = 0
    for point in candidate_stream(seed, side, rng):
        attempts += 1
        if attempts > 200000:
            raise RuntimeError("failed to obtain full-rank sample for %s" % tag)
        if not generic_oracle_point(point):
            continue
        sig, keys = signature(point)
        if keys != sig_keys or sig != target:
            continue
        W, S = scaled_w(point)
        row = eval_row_int(W, basis)
        if ranker.add(row):
            selected.append((point, W, S, row))
            if ranker.rank == len(basis):
                break

    matrix = []
    rhs = []
    sample_records = []
    for point, W, S, row in selected:
        remainder, amp, pole = evaluate_remainder(oracle, point)
        value = remainder * (S ** 8)
        matrix.append([str(x) for x in row])
        rhs.append(fstr(value))
        sample_records.append({
            "free": [fstr(x) for x in (point.b, point.c, point.d, point.e)],
            "W": [str(x) for x in W],
            "S": fstr(S),
            "R_scaled8": fstr(value),
        })

    solve_in = DATA / ("%s_solve_input.json" % tag)
    solve_out = DATA / ("%s_solve_output.json" % tag)
    with solve_in.open("w") as fh:
        json.dump({"matrix": matrix, "rhs": rhs}, fh, separators=(",", ":"))
    solver = HERE.with_name("solve_exact.wl")
    start = time.time()
    proc = subprocess.run(
        [str(WOLFRAM), "-script", str(solver), str(solve_in), str(solve_out)],
        stdout=subprocess.PIPE, stderr=subprocess.PIPE, universal_newlines=True,

